def __find_dose_action_point_window() -> bool:
    """Searches for the Dose action point window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the ro_treat.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(ROTreat.dose_Action_Points_Window) is not None else False


def __find_treatment_readiness_check_window(waitTimeout: int = 10000) -> bool:
    """Searches for the Treatment readiness check window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the ro_treat.py file context!

    :param int waitTimeout: Amount of time to wait (in milliseconds) for the Treatment Readiness Check window to appear
    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(ROTreat.treatment_Readiness_Check_Window, waitTimeout) is not None else False


def __find_verification_image_status_window(waitTimeout: int = 10000) -> bool:
    """Searches for the Verification image status window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the ro_treat.py file context!

    :param int waitTimeout: Amount of time to wait (in milliseconds) for the Verification Image Status window to appear
    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(ROTreat.verification_Image_Status_Window, waitTimeout) is not None else False


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_treatment_readiness_check_displayed(waitTimeout: int = 10000) -> bool:
    """Reports whether the Treatment Readiness Check window is on screen.

    The public counterpart to __find_treatment_readiness_check_window(). Every handler in this
    module swallows the window's absence so a missing popup never breaks a delivery flow, which
    leaves a test no way to assert the pre-checks actually ran -- this is that assertion.

    Built on does_object_exist(), NOT find_object(): find_object() falls back to returning the
    first Edit control in the AUT when its target is missing, so it can never report absence.

    :param int waitTimeout: Time in milliseconds to wait before reporting the window absent
    :return: True or False
    :rtype: bool
    """
    return CommonActions.does_object_exist(ROTreat.treatment_Readiness_Check_Window, waitTimeout)


