@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_treatment_readiness_ocr_available() -> bool:
    """Reports whether OCR can read the Treatment Readiness Check window.

    Squish ships no OCR engine -- Tesseract installs separately -- so probe before calling
    get_treatment_readiness_text().

    :return: True or False
    :rtype: bool
    """
    return CommonActions.is_ocr_available(ROTreat.treatment_Readiness_Check_Window)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_treatment_readiness_text() -> str:
    """Returns the readiness messages, warnings and acknowledgements as OCR reads them.

    The readiness list is a Clarion control that publishes no row objects, so OCR is the only
    way to read what the checks reported -- the same approach
    click_on_plan_site_from_list_on_treatment_readiness() already takes on this window.

    :raises RuntimeError: when the Treatment Readiness Check window is not displayed
    :return: OCR text of the window, or an empty string when nothing could be read
    :rtype: str
    """
    if not is_treatment_readiness_check_displayed():
        raise RuntimeError("Treatment Readiness Check window is not displayed")
    return str(CommonActions.get_all_text_via_ocr_in_object(ROTreat.treatment_Readiness_Check_Window) or "")


