@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def check_sending_dicom_confirmation_message(waitTimeout: int = 10) -> bool:
    """Check if confirmation message is dispalyed

    :param int waitTimeout: Time to wait for the confirmation message to appear
    """
    if waitTimeout >= 25:
        for i in range(waitTimeout//5):
            successful = CommonActions.wait_for_object_to_appear(DandI.sending_Dicom_Data_Message_Pane, 5)
            if successful:
                return True
        return False
    else:
        return CommonActions.wait_for_object_to_appear(DandI.sending_Dicom_Data_Message_Pane, waitTimeout)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def wait_for_sending_dicom_message_to_disappear(waitTimeout: int = 180) -> bool:
    """Wait for the Sending DICOM data message to disappear after a specified amount of time

    :param int waitTimeout: Time to wait for the dicom data message to disappear
    """
    return CommonActions.wait_for_object_to_disappear(DandI.sending_Dicom_Data_Message_Pane, waitTimeout)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def acknowledge_error_dialog() -> bool:
    """Clicks the OK button to acknowledge the Error message.
    Example use case: "An error has occured while synchornizing data with Care Rules." dialog

    :return: True if an error has been acknowledged, False otherwise
    :rtype: bool
    """
    # does_object_exist(), NOT find_object(): find_object() falls back to returning the first
    # Edit control in the AUT when its target is missing, so "is not None" was true even with
    # no error dialog on screen and this reported a phantom error on every call.
    if CommonActions.does_object_exist(DandI.error_Window, 3000):
        CommonActions.left_click_object(DandI.error_Window_OK_Button)
        return True
    return False


