@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_patient_synchronization_dialog_yes_button(waitTimeout: int = 6000, waitAfterClick: int = 1000) -> bool:
    """Clicks the Yes button to acknowledge the Patient Synchronization message.
    Example use case 1: "XVI is offline or busy, do you want to retry?"
    Example use case 2: "Do you want to treat without XVI integration?"

    :param int waitTimeout: Time to wait (in milliseconds) for the warning message to appear
    :param int waitAfterClick: Time to wait (in milliseconds) after acknowledging the message
    :return: True if the Patient Synchronization message was acknowledged, False otherwise
    """
    try:
        CommonActions.find_object(DandI.patient_sync_Window, timeout=waitTimeout)
        CommonActions.left_click_object(DandI.patient_sync_Window_Yes_Button)
        time.sleep(waitAfterClick/1000)
        return True
    except FailedToFindObject:
        return False


