@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def acknowledge_all_fields_treated_warning(waitTimeout: int = 3000, ackProjectedRxMisMatches: bool = False) -> bool:
    """Clicks the Yes button to acknowledge the Warning message and close the dialog.

    :param int waitTimeout: Time to wait for the warning message to appear
    :param bool ackProjectedRxMisMatches: True if the projected Rx mismatches warning should be acknowledged
    :return: True if the warning was acknowledged, False otherwise
    """
    try:
        CommonActions.find_object(MosaiqCoreObjects.question_Window, timeout=waitTimeout)
        CommonActions.find_object(MosaiqCoreObjects.question_Message_All_Fields_Treated, timeout=waitTimeout)
        CommonActions.left_click_object(MosaiqCoreObjects.question_Yes_Button)
        if ackProjectedRxMisMatches:
            acknowledge_projected_rx_mismatches_warning()
        return True
    except FailedToFindObject:
        return False


