@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def acknowledge_prescription_dose_will_be_exceeded_dialog(waitTimeout: int = 3000) -> bool:
    """
    Waits for the "Prescription Dose will be exceeded by..." Warning dialog to appear and clicks
    on the Yes button.

    :param int waitTimeout: Amount of time to wait (in milliseconds) for the "Prescription Dose
                            will be exceeded by..."Warning dialog to appear
    """
    try:
        CommonActions.find_object(ROTreat.warning_Window, timeout=waitTimeout)
        if "Prescription Dose will be exceeded" in CommonActions.get_objects_text_value(
            CommonActions.find_object(ROTreat.warning_Label)):
            CommonActions.left_click_object(ROTreat.warning_Window_Yes_Button)
            return True
        return False
    except FailedToFindObject:
        return False


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def machine_qa_override_approval(password: str = "impac", waitTimeout: int = 3000) -> bool:
    """Select the Override checkbox (assumes the first row), enter the approval password
    in the Machine QA Override Approval window and select the OK button

    Note: The Spacebar on a keyboard can also be used to select the Override checkbox

    :param str password: The password to be entered in the Machine QA Override Approval window
    :param int waitTimeout: The amount of time to wait for the Machine QA Override Approval window to appear
    :return: True if the Machine QA Override Approval window is successfully closed (approved), False otherwise
    """
    try:
        CommonActions.find_object(ROTreat.machine_QA_Override_Window, timeout=waitTimeout)
        CommonActions.left_click_object(ROTreat.qa_Override_First_Row_Cell_Checkbox)
        CommonActions.type_in_textfield(ROTreat.qa_Override_Approval_Password_Edit_Field, password)
        CommonActions.left_click_object(ROTreat.qa_Override_Ok_Button)
        return CommonActions.wait_for_object_to_disappear(ROTreat.machine_QA_Override_Window)
    except FailedToFindObject:
        return False